// W3 (Normalizar Criterios) no reenvía id_solicitud en su salida — se restaura acá desde
// el contrato de entrada original, para no depender de que el motor lo corrija.
const idOriginal = // F4-03: el id original viaja en el item del llamador (antes se leia de 'Aplanar contrato de entrada').
$('When Executed by Another Workflow').item.json.id_solicitud;
return { json: { ...$json, id_solicitud: idOriginal } };

const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const captura = get('Capturar ID de solicitud');
const idSolicitud = $json.id_solicitud || captura.id_solicitud || '(sin id)';
const servicio = $json.servicio || '(sin servicio)';
const nodoFallido = 'Motor Criterios y Precio';
const flujo = $workflow.name;
const esExcepcion = typeof $json.ok === 'undefined';
const tipoError = esExcepcion ? 'Excepción al invocar el motor de cálculo (W3)' : 'Rechazo del motor de cálculo (ok=false)';
const mensajeError = $json.error || JSON.stringify($json.error || {}) || 'El motor rechazó el cálculo sin mensaje';
const fechaError = DateTime.now().setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm:ss');
const emailBody = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background-color:#F2F5F9;font-family:Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F2F5F9"><tr><td align="center" style="padding:32px 16px;">
<table width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#FFFFFF" style="max-width:600px;border-radius:12px;overflow:hidden;">
<tr><td bgcolor="#001489" align="center" style="padding:28px 40px;">
<p style="font-size:11px;font-weight:600;color:rgba(255,255,255,0.65);text-transform:uppercase;letter-spacing:3px;margin:0;">Servicios de Información</p>
</td></tr>
<tr><td bgcolor="#D64545" align="center" style="padding:11px 32px;">
<p style="font-size:12px;font-weight:700;color:#FFFFFF;text-transform:uppercase;letter-spacing:2px;margin:0;">⚠️ Motor rechazó el cálculo</p>
</td></tr>
<tr><td bgcolor="#FFFFFF" style="padding:32px 40px;">
<p style="font-size:14px;color:#404e4f;margin:0 0 16px 0;line-height:1.7;">El motor de criterios y precio rechazó el cálculo de esta propuesta (Workflow 3). No se generó cotización.</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Flujo:</strong> ${flujo}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Tipo de error:</strong> ${tipoError}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">ID solicitud:</strong> ${idSolicitud}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Servicio:</strong> ${servicio}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Nodo fallido:</strong> ${nodoFallido}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Mensaje:</strong> ${mensajeError}</p>
<p style="font-size:13px;color:#212120;margin:0;"><strong style="color:#001489;">Fecha:</strong> ${fechaError}</p>
</td></tr>
</table></td></tr></table></body></html>`;
return { json: { id_solicitud: idSolicitud, flujo, tipo_error: tipoError, workflow_origen: 'workflow-formulario', nodo_fallido: nodoFallido, mensaje_error: mensajeError, fecha_error: fechaError, emailBody } };

// F4-03: la salida de error del guardado vive ahora en este subflujo (antes iba al preparador de W2-A).
const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const j = $json || {};
const mensaje = (j.error && (j.error.message || j.error.description)) || 'Fallo al guardar la cotización';
const id = j.id_solicitud || get('Restaurar id_solicitud').id_solicitud || '(sin id)';
const emailBody = '<p>Error guardando la cotización en Cotizaciones_CCB.</p><ul><li><b>Solicitud:</b> ' + id + '</li><li><b>Detalle:</b> ' + mensaje + '</li></ul>';
return { json: { id_solicitud: id, workflow_origen: 'W2-A-guardar-criterios', nodo_fallido: 'Data Table - Guardar Cotización',
                 mensaje_error: mensaje, emailBody } };

